          const slider = document.createElement('input');
          slider.type = 'range';
          slider.min = '0';
          slider.max = '100';
          slider.step = '1';
          slider.className = 'ani-volume-slider';
          slider.setAttribute('aria-label', '音量');
          const syncVolume = () => {
            const effVol = volumeVideo.muted ? 0 : volumeVideo.volume;
            const pct = Math.round(effVol * 100);
            slider.value = String(pct);
            slider.style.setProperty('--ani-range-pct', `${pct}%`);
            const lvl = pct <= 0 ? '0' : pct < 34 ? '1' : pct < 68 ? '2' : '3';
            const muteBtn = volumePanel.querySelector('.vjs-mute-control');
            if (muteBtn) {
              muteBtn.dataset.aniVol = lvl;
              muteBtn.classList.remove('vjs-vol-0', 'vjs-vol-1', 'vjs-vol-2', 'vjs-vol-3');
              muteBtn.classList.add(`vjs-vol-${lvl}`);
            }
          };
          syncVolume();
          volumeVideo.addEventListener('volumechange', syncVolume);
          slider.addEventListener('input', () => {
            const val = Number(slider.value);
            volumeVideo.volume = val / 100;
            volumeVideo.muted = val === 0;
            syncVolume();
          });
          volumePanel.addEventListener(
            'wheel',
            (event) => {
              event.preventDefault();
              const delta = event.deltaY < 0 ? 0.05 : -0.05;
              const next = Math.max(
                0,
                Math.min(1, (volumeVideo.muted && delta > 0 ? 0 : volumeVideo.volume) + delta),
              );
              if (delta > 0 && volumeVideo.muted) volumeVideo.muted = false;
              volumeVideo.volume = next;
              if (next <= 0) volumeVideo.muted = true;
              syncVolume();
            },
            { passive: false },
          );
