                  '.redeem-card .programtitle{display:flex!important;align-items:center;gap:12px;color:#e7edf5!important;font:600 24px/1.4 system-ui,sans-serif!important}.redeem-card .programtitle svg{width:28px;height:28px;flex:none;color:#68cbd2}.redeem-card .redeem-notice{font:14px/1.7 system-ui,sans-serif!important;color:#c4d1df!important;white-space:nowrap!important;margin:20px 0 24px!important}@media(max-width:620px){.redeem-card .redeem-notice{white-space:normal!important}}';
                doc.head.append(detailStyle);
